fn native_main_window_handle(cc: &eframe::CreationContext<'_>) -> Option<isize> {
    let window = cc.window_handle().ok()?;
    match window.as_raw() {
        RawWindowHandle::Win32(handle) => Some(handle.hwnd.get()),
        _ => None,
    }
}

