#[derive(Debug)]
struct InstallJobFailure {
    message: String,
    recovery_required: bool,
    download_failure: Option<DownloadFailureMetadata>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct DownloadFailureMetadata {
    category: DownloadFaultKind,
    retry_count: u8,
    retained_bytes: u64,
}

impl InstallJobFailure {
    fn normal(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            recovery_required: false,
            download_failure: None,
        }
    }

    fn recovery_required(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
            recovery_required: true,
            download_failure: None,
        }
    }
}

impl From<String> for InstallJobFailure {
    fn from(message: String) -> Self {
        Self::normal(message)
    }
}

impl From<InstallError> for InstallJobFailure {
    fn from(error: InstallError) -> Self {
        let download_failure = match &error {
            InstallError::DownloadFailed {
                category,
                retry_count,
                retained_bytes,
                ..
            } => Some(DownloadFailureMetadata {
                category: *category,
                retry_count: *retry_count,
                retained_bytes: *retained_bytes,
            }),
            _ => None,
        };
        if error.requires_recovery() {
            let mut failure = Self::recovery_required(error.to_string());
            failure.download_failure = download_failure;
            failure
        } else {
            let mut failure = Self::normal(error.to_string());
            failure.download_failure = download_failure;
            failure
        }
    }
}

fn send_install_progress(
    tx: &AppEventSink,
    job_id: u64,
    model_id: &str,
    progress: InstallProgress,
) {
    let _ = tx.send(AppEvent::ModelDownloadProgress {
        job_id,
        model_id: model_id.to_owned(),
        progress,
    });
}

fn send_verified_install_result(
    tx: &AppEventSink,
    job_id: u64,
    model_id: String,
    result: Result<VerifiedInstallResult, InstallJobFailure>,
) {
    match result {
        Ok(result) => {
            let _ = tx.send(AppEvent::VerifiedInstallDone {
                job_id,
                model_id,
                result: Box::new(result),
            });
        }
        Err(failure) => {
            let _ = tx.send(AppEvent::VerifiedInstallFailed {
                job_id,
                model_id,
                message: failure.message,
                recovery_required: failure.recovery_required,
                download_failure: failure.download_failure,
            });
        }
    }
}

fn send_verified_install_preparation(
    tx: &AppEventSink,
    job_id: u64,
    model_id: String,
    result: Result<PreparedVerifiedInstall, InstallJobFailure>,
) {
    match result {
        Ok(prepared) => {
            let _ = tx.send(AppEvent::VerifiedInstallPrepared {
                job_id,
                model_id,
                prepared: Box::new(prepared),
            });
        }
        Err(failure) => {
            let _ = tx.send(AppEvent::VerifiedInstallFailed {
                job_id,
                model_id,
                message: failure.message,
                recovery_required: failure.recovery_required,
                download_failure: failure.download_failure,
            });
        }
    }
}

fn activation_journal_path() -> PathBuf {
    config::artifact_state_storage_dir().join("activation-journal.json")
}

fn failure_after_safe_rollback(
    journal: ActivationJournal,
    message: impl Into<String>,
) -> InstallJobFailure {
    let message = message.into();
    match journal.clear() {
        Ok(()) => InstallJobFailure::normal(message),
        Err(clear_error) => InstallJobFailure::recovery_required(format!(
            "{message}. Rollback completed, but the activation journal could not be cleared: {clear_error}"
        )),
    }
}

fn failure_after_activated_artifact_rollback(
    journal: ActivationJournal,
    model: FileReplacement,
    manifest: Option<FileReplacement>,
    message: impl Into<String>,
) -> InstallJobFailure {
    let manifest_rollback = manifest.and_then(|replacement| replacement.rollback().err());
    let model_rollback = model.rollback().err();
    if manifest_rollback.is_none() && model_rollback.is_none() {
        return failure_after_safe_rollback(journal, message);
    }
    let message = message.into();
    InstallJobFailure::recovery_required(format!(
        "{message}{}{}",
        manifest_rollback
            .as_ref()
            .map(|error| format!(". Installed-model manifest rollback also failed: {error}"))
            .unwrap_or_default(),
        model_rollback
            .as_ref()
            .map(|error| format!(". Model rollback also failed: {error}"))
            .unwrap_or_default(),
    ))
}

struct VerifiedInstallPreparationRequest {
    config: AppConfig,
    model_id: ModelId,
    cancellation: InstallCancellation,
    source: VerifiedInstallSource,
    expected_target_identity: crate::disk_space::CanonicalTargetIdentity,
}

/// The UI can only construct this request from a typed backend catalog card.
/// It carries source facts, never an arbitrary URL or filesystem path.
#[derive(Clone, Debug)]
struct TrustedRemoteInstallRequest {
    artifact: TrustedArtifact,
    display_name: String,
    description: String,
    languages: Vec<String>,
    recommended: bool,
}

#[derive(Clone, Debug)]
enum VerifiedInstallSource {
    NormalizedCatalog,
    TrustedRemote(TrustedRemoteInstallRequest),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ArtifactInstallPhase {
    QueuedTransfer,
    Transferring,
    WaitingForFinalizer,
    Finalizing,
}

impl ArtifactInstallPhase {
    fn allows_cancellation(self) -> bool {
        matches!(
            self,
            Self::QueuedTransfer | Self::Transferring | Self::WaitingForFinalizer
        )
    }

    fn status_label(self) -> &'static str {
        match self {
            Self::QueuedTransfer => "Queued for download",
            Self::Transferring => "Downloading",
            Self::WaitingForFinalizer => "Waiting for verification",
            Self::Finalizing => "Verifying and activating",
        }
    }
}

#[derive(Debug)]
struct ArtifactInstallJob {
    handle: (u64, InstallCancellation),
    phase: ArtifactInstallPhase,
    download_activity: Option<DownloadActivity>,
    download_diagnostic: DownloadDiagnosticProgress,
    source: Option<VerifiedInstallSource>,
    download_config: Option<AppConfig>,
    target_identity: Option<crate::disk_space::CanonicalTargetIdentity>,
    reservation: Option<ArtifactDiskReservation>,
    prepared: Option<PreparedVerifiedInstall>,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct DownloadDiagnosticProgress {
    completed_bytes: u64,
    total_bytes: Option<u64>,
    retry_number: Option<u32>,
    fault_category: Option<DownloadFaultCategory>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ArtifactDiskReservation {
    volume: String,
    remaining_bytes: u64,
    kind: ArtifactDiskReservationKind,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ArtifactDiskReservationKind {
    ModelArtifact,
}

#[derive(Debug)]
struct ArtifactTransferLaunch {
    job_id: u64,
    model_id: String,
    config: AppConfig,
    cancellation: InstallCancellation,
    source: VerifiedInstallSource,
    expected_target_identity: crate::disk_space::CanonicalTargetIdentity,
}

#[derive(Debug)]
struct ArtifactFinalizerLaunch {
    job_id: u64,
    model_id: String,
    cancellation: InstallCancellation,
    prepared: PreparedVerifiedInstall,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum ArtifactCancellationOutcome {
    Missing,
    SignalledTransfer { job_id: u64 },
    SettledBeforeFinalizer { job_id: u64 },
    FinalizerAlreadyActive { job_id: u64 },
}

#[derive(Debug, Default)]
struct ArtifactInstallCoordinator {
    jobs: HashMap<String, ArtifactInstallJob>,
    transfer_queue: VecDeque<String>,
    finalizer_queue: VecDeque<String>,
    active_transfers: usize,
    active_finalizer: Option<u64>,
    target_owners: HashMap<crate::disk_space::CanonicalTargetIdentity, u64>,
    reserved_by_volume: HashMap<String, u64>,
    recovery_frozen: bool,
}

impl ArtifactInstallCoordinator {
    fn is_empty(&self) -> bool {
        self.jobs.is_empty()
    }

    fn recovery_is_frozen(&self) -> bool {
        self.recovery_frozen
    }

    fn contains_key(&self, model_id: &str) -> bool {
        self.jobs.contains_key(model_id)
    }

    fn get(&self, model_id: &str) -> Option<&(u64, InstallCancellation)> {
        self.jobs.get(model_id).map(|job| &job.handle)
    }

    fn accepts_progress(&self, model_id: &str, job_id: u64) -> bool {
        self.jobs.get(model_id).is_some_and(|job| {
            job.handle.0 == job_id
                && matches!(
                    job.phase,
                    ArtifactInstallPhase::Transferring | ArtifactInstallPhase::Finalizing
                )
        })
    }

    fn phase_for_model(&self, model_id: &str) -> Option<ArtifactInstallPhase> {
        self.jobs.get(model_id).map(|job| job.phase)
    }

    fn aggregate_status(&self) -> Option<String> {
        (self.jobs.len() > 1).then(|| {
            let downloading = self
                .jobs
                .values()
                .filter(|job| job.phase == ArtifactInstallPhase::Transferring)
                .count();
            let queued = self
                .jobs
                .values()
                .filter(|job| job.phase == ArtifactInstallPhase::QueuedTransfer)
                .count();
            let waiting = self
                .jobs
                .values()
                .filter(|job| job.phase == ArtifactInstallPhase::WaitingForFinalizer)
                .count();
            let finalizing = usize::from(self.active_finalizer.is_some());
            format!(
                "Installing {} models: {downloading} downloading, {queued} queued, {waiting} waiting for verification, {finalizing} verifying.",
                self.jobs.len()
            )
        })
    }

    #[cfg(test)]
    fn get_job(&self, model_id: &str) -> Option<&ArtifactInstallJob> {
        self.jobs.get(model_id)
    }

    fn values(&self) -> impl Iterator<Item = &(u64, InstallCancellation)> {
        self.jobs.values().map(|job| &job.handle)
    }

    /// Test-only compatibility for fixtures that seed a correlated job.
    #[cfg(test)]
    fn insert(
        &mut self,
        model_id: String,
        handle: (u64, InstallCancellation),
    ) -> Option<(u64, InstallCancellation)> {
        let previous = self.jobs.insert(
            model_id,
            ArtifactInstallJob {
                handle,
                phase: ArtifactInstallPhase::Transferring,
                download_activity: None,
                download_diagnostic: DownloadDiagnosticProgress::default(),
                source: None,
                download_config: None,
                target_identity: None,
                reservation: None,
                prepared: None,
            },
        );
        previous.map(|job| job.handle)
    }

    fn admit(
        &mut self,
        model_id: String,
        admission: managed_downloads::ModelDownloadAdmission,
        config: AppConfig,
        source: VerifiedInstallSource,
    ) -> Result<u64, String> {
        if self.recovery_frozen {
            return Err(
                "Artifact recovery is required before another installation can start.".to_owned(),
            );
        }
        if self.jobs.contains_key(&model_id) {
            return Err(format!("{model_id} is already being installed."));
        }
        if self.target_owners.contains_key(&admission.target_identity) {
            return Err(format!(
                "Another installation already owns the target {}.",
                admission.target.display()
            ));
        }
        let already_reserved = self
            .reserved_by_volume
            .get(&admission.disk.volume)
            .copied()
            .unwrap_or(0);
        let required = already_reserved
            .checked_add(admission.disk.additional_bytes)
            .and_then(|bytes| bytes.checked_add(crate::disk_space::SAFETY_HEADROOM_BYTES))
            .ok_or_else(|| "aggregate download-space reservation overflowed".to_owned())?;
        if required > admission.disk.available_bytes {
            return Err(format!(
                "Install disabled: {} free is required on {} for active downloads (including Scribe's {} safety headroom); only {} is available.",
                format_bytes(required),
                admission.disk.volume,
                format_bytes(crate::disk_space::SAFETY_HEADROOM_BYTES),
                format_bytes(admission.disk.available_bytes),
            ));
        }
        let job_id = INSTALL_JOB_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        self.target_owners
            .insert(admission.target_identity.clone(), job_id);
        self.reserved_by_volume.insert(
            admission.disk.volume.clone(),
            already_reserved + admission.disk.additional_bytes,
        );
        self.jobs.insert(
            model_id.clone(),
            ArtifactInstallJob {
                handle: (job_id, InstallCancellation::default()),
                phase: ArtifactInstallPhase::QueuedTransfer,
                download_activity: None,
                download_diagnostic: DownloadDiagnosticProgress::default(),
                source: Some(source),
                download_config: Some(config),
                target_identity: Some(admission.target_identity),
                reservation: Some(ArtifactDiskReservation {
                    volume: admission.disk.volume,
                    remaining_bytes: admission.disk.additional_bytes,
                    kind: ArtifactDiskReservationKind::ModelArtifact,
                }),
                prepared: None,
            },
        );
        self.transfer_queue.push_back(model_id);
        Ok(job_id)
    }

    fn take_ready_transfers(&mut self) -> Vec<ArtifactTransferLaunch> {
        let mut launches = Vec::new();
        if self.recovery_frozen {
            return launches;
        }
        while self.active_transfers < MAX_CONCURRENT_MODEL_TRANSFERS {
            let Some(model_id) = self.transfer_queue.pop_front() else {
                break;
            };
            let Some(job) = self.jobs.get_mut(&model_id) else {
                continue;
            };
            if job.phase != ArtifactInstallPhase::QueuedTransfer {
                continue;
            }
            let Some(config) = job.download_config.take() else {
                continue;
            };
            let Some(source) = job.source.take() else {
                continue;
            };
            job.phase = ArtifactInstallPhase::Transferring;
            self.active_transfers += 1;
            launches.push(ArtifactTransferLaunch {
                job_id: job.handle.0,
                model_id,
                config,
                cancellation: job.handle.1.clone(),
                source,
                expected_target_identity: job
                    .target_identity
                    .clone()
                    .expect("admitted transfer has no canonical target identity"),
            });
        }
        launches
    }

    fn update_download_reservation(
        &mut self,
        model_id: &str,
        job_id: u64,
        remaining_bytes: u64,
    ) -> bool {
        let Some(job) = self.jobs.get_mut(model_id) else {
            return false;
        };
        if job.handle.0 != job_id {
            return false;
        }
        let reservation = match job.phase {
            ArtifactInstallPhase::Transferring => job.reservation.as_mut(),
            ArtifactInstallPhase::Finalizing => None,
            ArtifactInstallPhase::QueuedTransfer | ArtifactInstallPhase::WaitingForFinalizer => {
                None
            }
        };
        let Some(reservation) = reservation else {
            return false;
        };
        let remaining_bytes = remaining_bytes.min(reservation.remaining_bytes);
        let released = reservation.remaining_bytes - remaining_bytes;
        reservation.remaining_bytes = remaining_bytes;
        let mut remove_volume = false;
        if let Some(total) = self.reserved_by_volume.get_mut(&reservation.volume) {
            *total = total.saturating_sub(released);
            remove_volume = *total == 0;
        }
        if remove_volume {
            self.reserved_by_volume.remove(&reservation.volume);
        }
        true
    }

    fn initialize_download_diagnostic(
        &mut self,
        model_id: &str,
        job_id: u64,
        completed_bytes: u64,
        total_bytes: Option<u64>,
    ) -> bool {
        let Some(job) = self.jobs.get_mut(model_id) else {
            return false;
        };
        if job.handle.0 != job_id {
            return false;
        }
        job.download_diagnostic.completed_bytes = completed_bytes;
        job.download_diagnostic.total_bytes = total_bytes;
        true
    }

    fn update_download_diagnostic_progress(
        &mut self,
        model_id: &str,
        job_id: u64,
        completed_bytes: u64,
        total_bytes: Option<u64>,
    ) -> bool {
        let Some(job) = self.jobs.get_mut(model_id) else {
            return false;
        };
        if job.handle.0 != job_id
            || !matches!(
                job.phase,
                ArtifactInstallPhase::Transferring | ArtifactInstallPhase::Finalizing
            )
        {
            return false;
        }
        job.download_diagnostic.completed_bytes = completed_bytes;
        job.download_diagnostic.total_bytes = total_bytes;
        true
    }

    fn download_diagnostic_progress(
        &self,
        model_id: &str,
        job_id: u64,
    ) -> Option<DownloadDiagnosticProgress> {
        self.jobs
            .get(model_id)
            .filter(|job| job.handle.0 == job_id)
            .map(|job| job.download_diagnostic)
    }

    fn record_terminal_download_failure(
        &mut self,
        model_id: &str,
        job_id: u64,
        download_failure: Option<DownloadFailureMetadata>,
        recovery_required: bool,
    ) -> Option<DownloadDiagnosticProgress> {
        let job = self
            .jobs
            .get_mut(model_id)
            .filter(|job| job.handle.0 == job_id)?;
        if let Some(failure) = download_failure {
            job.download_diagnostic.completed_bytes = failure.retained_bytes;
            job.download_diagnostic.retry_number = Some(u32::from(failure.retry_count));
            job.download_diagnostic.fault_category =
                Some(download_fault_category(failure.category));
        } else {
            job.download_diagnostic.fault_category = Some(if recovery_required {
                DownloadFaultCategory::LocalStorage
            } else {
                DownloadFaultCategory::Unknown
            });
        }
        Some(job.download_diagnostic)
    }

    fn record_terminal_download_fault(
        &mut self,
        model_id: &str,
        job_id: u64,
        category: DownloadFaultCategory,
    ) -> Option<DownloadDiagnosticProgress> {
        let job = self
            .jobs
            .get_mut(model_id)
            .filter(|job| job.handle.0 == job_id)?;
        job.download_diagnostic.fault_category = Some(category);
        Some(job.download_diagnostic)
    }

    /// Returns the preceding activity only when this is a correlated transfer
    /// transition. Byte-only events carry `None` and intentionally do not
    /// clear the retained activity state.
    fn update_download_activity(
        &mut self,
        model_id: &str,
        job_id: u64,
        activity: DownloadActivity,
    ) -> Option<Option<DownloadActivity>> {
        let job = self.jobs.get_mut(model_id)?;
        if job.handle.0 != job_id || job.phase != ArtifactInstallPhase::Transferring {
            return None;
        }
        if job.download_activity == Some(activity) {
            return None;
        }
        match activity {
            DownloadActivity::RetryScheduled { attempt, cause, .. } => {
                job.download_diagnostic.retry_number = Some(u32::from(attempt));
                job.download_diagnostic.fault_category = Some(download_fault_category(cause));
            }
            DownloadActivity::Stalled => {
                job.download_diagnostic.fault_category = Some(DownloadFaultCategory::Timeout);
            }
            DownloadActivity::Active => {}
        }
        Some(job.download_activity.replace(activity))
    }

    fn download_activity_for_model(&self, model_id: &str) -> Option<DownloadActivity> {
        self.jobs
            .get(model_id)
            .filter(|job| job.phase == ArtifactInstallPhase::Transferring)
            .and_then(|job| job.download_activity)
    }

    fn next_finalizer_model(&self) -> Option<String> {
        if self.recovery_frozen || self.active_finalizer.is_some() {
            return None;
        }
        let model_id = self.finalizer_queue.front()?;
        self.jobs
            .get(model_id)
            .is_some_and(|job| job.phase == ArtifactInstallPhase::WaitingForFinalizer)
            .then(|| model_id.clone())
    }
    fn release_reservation(&mut self, reservation: ArtifactDiskReservation) {
        let mut remove_volume = false;
        if let Some(total) = self.reserved_by_volume.get_mut(&reservation.volume) {
            *total = total.saturating_sub(reservation.remaining_bytes);
            remove_volume = *total == 0;
        }
        if remove_volume {
            self.reserved_by_volume.remove(&reservation.volume);
        }
    }

    fn mark_prepared(
        &mut self,
        model_id: &str,
        job_id: u64,
        prepared: PreparedVerifiedInstall,
    ) -> bool {
        let Some(job) = self.jobs.get_mut(model_id) else {
            return false;
        };
        if job.handle.0 != job_id || job.phase != ArtifactInstallPhase::Transferring {
            return false;
        }
        self.active_transfers = self.active_transfers.saturating_sub(1);
        let reservation = job.reservation.take();
        job.download_activity = None;
        job.phase = ArtifactInstallPhase::WaitingForFinalizer;
        job.prepared = Some(prepared);
        self.finalizer_queue.push_back(model_id.to_owned());
        if let Some(reservation) = reservation {
            self.release_reservation(reservation);
        }
        true
    }

    fn take_next_finalizer(&mut self) -> Option<ArtifactFinalizerLaunch> {
        if self.recovery_frozen || self.active_finalizer.is_some() {
            return None;
        }
        while let Some(model_id) = self.finalizer_queue.pop_front() {
            let Some(job) = self.jobs.get_mut(&model_id) else {
                continue;
            };
            if job.phase != ArtifactInstallPhase::WaitingForFinalizer {
                continue;
            }
            let prepared = job.prepared.take()?;
            job.phase = ArtifactInstallPhase::Finalizing;
            self.active_finalizer = Some(job.handle.0);
            return Some(ArtifactFinalizerLaunch {
                job_id: job.handle.0,
                model_id,
                cancellation: job.handle.1.clone(),
                prepared,
            });
        }
        None
    }

    fn finish(&mut self, model_id: &str, job_id: u64) -> bool {
        let Some(job) = self.jobs.get(model_id) else {
            return false;
        };
        if job.handle.0 != job_id {
            return false;
        }
        let was_transfer = job.phase == ArtifactInstallPhase::Transferring;
        let was_finalizer = job.phase == ArtifactInstallPhase::Finalizing;
        let target = job.target_identity.clone();
        let reservation = job.reservation.clone();
        self.jobs.remove(model_id);
        self.transfer_queue.retain(|queued| queued != model_id);
        self.finalizer_queue.retain(|queued| queued != model_id);
        if was_transfer {
            self.active_transfers = self.active_transfers.saturating_sub(1);
        }
        if was_finalizer && self.active_finalizer == Some(job_id) {
            self.active_finalizer = None;
        }
        if let Some(target) = target {
            self.target_owners.remove(&target);
        }
        if let Some(reservation) = reservation {
            self.release_reservation(reservation);
        }
        true
    }

    fn cancel(&mut self, model_id: &str) -> ArtifactCancellationOutcome {
        let Some(job) = self.jobs.get(model_id) else {
            return ArtifactCancellationOutcome::Missing;
        };
        let job_id = job.handle.0;
        match job.phase {
            ArtifactInstallPhase::QueuedTransfer | ArtifactInstallPhase::WaitingForFinalizer => {
                job.handle.1.cancel();
                let settled = self.finish(model_id, job_id);
                debug_assert!(settled);
                ArtifactCancellationOutcome::SettledBeforeFinalizer { job_id }
            }
            ArtifactInstallPhase::Transferring => {
                job.handle.1.cancel();
                ArtifactCancellationOutcome::SignalledTransfer { job_id }
            }
            ArtifactInstallPhase::Finalizing => {
                ArtifactCancellationOutcome::FinalizerAlreadyActive { job_id }
            }
        }
    }

    fn freeze_for_recovery(&mut self, failing_job_id: Option<u64>) -> Vec<(String, bool)> {
        self.recovery_frozen = true;
        let siblings = self
            .jobs
            .iter()
            .filter_map(|(model_id, job)| {
                if Some(job.handle.0) == failing_job_id {
                    return None;
                }
                job.handle.1.cancel();
                let settled = matches!(
                    job.phase,
                    ArtifactInstallPhase::QueuedTransfer
                        | ArtifactInstallPhase::WaitingForFinalizer
                );
                Some((model_id.clone(), job.handle.0, settled))
            })
            .collect::<Vec<_>>();
        for (model_id, job_id, settled) in &siblings {
            if *settled {
                self.finish(model_id, *job_id);
            }
        }
        siblings
            .into_iter()
            .map(|(model_id, _, settled)| (model_id, settled))
            .collect()
    }
}

#[derive(Clone, Debug)]
enum RemoteModelCardAction {
    InstallNormalized(ModelId),
    InstallTrusted(TrustedRemoteInstallRequest),
    CancelInstall(ModelId),
    DiscardNormalizedPartial(ModelId),
    DiscardTrustedPartial(TrustedArtifact),
    SelectInstalled(ModelId),
    RemoveInstalled(ModelId),
}

fn prepare_verified_install(
    request: VerifiedInstallPreparationRequest,
    progress: &dyn Fn(InstallProgress),
) -> Result<PreparedVerifiedInstall, InstallJobFailure> {
    let VerifiedInstallPreparationRequest {
        config,
        model_id,
        cancellation,
        source,
        expected_target_identity,
    } = request;
    let (model, manifest_source, remote_install_request) = match source {
        VerifiedInstallSource::NormalizedCatalog => {
            let model = managed_downloads::prepare_model(
                &config,
                &model_id,
                &expected_target_identity,
                &cancellation,
                progress,
            )
            .map_err(InstallJobFailure::from)?;
            let source = installed_manifest::ArtifactSource::normalized(&model_id)
                .map_err(|error| error.to_string())?;
            (model, source, None)
        }
        VerifiedInstallSource::TrustedRemote(request) => {
            let model = managed_downloads::prepare_trusted_gguf_model(
                &config,
                &request.artifact,
                &expected_target_identity,
                &cancellation,
                progress,
            )
            .map_err(InstallJobFailure::from)?;
            let source = installed_manifest::ArtifactSource::trusted_gguf(
                request.artifact.model_id.clone(),
                request.artifact.revision.clone(),
                request.artifact.filename.clone(),
                request.artifact.size_bytes,
                request.artifact.expected_sha256.clone(),
            );
            (model, source, Some(request))
        }
    };
    if cancellation.is_cancelled() {
        return Err(InstallJobFailure::normal(
            "Installation cancelled. The verified partial was retained for Resume.",
        ));
    }

    Ok(PreparedVerifiedInstall {
        model_id,
        model,
        manifest_source,
        remote_install_request,
    })
}

fn run_verified_install_finalizer(
    config: AppConfig,
    service: TranscriptionService,
    cancellation: InstallCancellation,
    prepared: PreparedVerifiedInstall,
    progress: &dyn Fn(InstallProgress),
) -> Result<VerifiedInstallResult, InstallJobFailure> {
    let PreparedVerifiedInstall {
        model_id,
        model,
        manifest_source,
        remote_install_request,
    } = prepared;
    if cancellation.is_cancelled() {
        return Err(InstallJobFailure::normal(
            "Installation cancelled while waiting for verification. The verified partial was retained for Resume.",
        ));
    }
    service.unload_runtime().map_err(|error| {
        InstallJobFailure::normal(format!(
            "Could not release the active speech artifact before install: {error}"
        ))
    })?;
    progress(InstallProgress {
        stage: InstallStage::HealthChecking,
        completed_bytes: model.size_bytes,
        total_bytes: model.size_bytes,
        bytes_per_second: None,
        download_activity: None,
    });
    let verified_smoke = service
        .verify_installation_candidate_for_activation(
            InstallationCandidate::pinned(
                model_id.clone(),
                model.path.clone(),
                ArtifactFormat::Gguf,
                manifest_source.expected_size_bytes,
                manifest_source.expected_sha256.clone(),
            ),
            &cancellation,
        )
        .map_err(|error| InstallJobFailure::normal(error.to_string()))?;
    if cancellation.is_cancelled() {
        return Err(InstallJobFailure::normal(
            "Installation cancelled after smoke testing; no artifacts were activated.",
        ));
    }
    progress(InstallProgress {
        stage: InstallStage::Activating,
        completed_bytes: model.size_bytes,
        total_bytes: model.size_bytes,
        bytes_per_second: None,
        download_activity: None,
    });
    let prior_config_fingerprint = config::settings::artifact_config_fingerprint(&config)
        .map_err(|error| format!("could not fingerprint pre-install artifact settings: {error}"))?;
    let smoke = verified_smoke
        .authorize_activation(
            &model_id,
            &model.path,
            model.size_bytes,
            &model.sha256,
            &cancellation,
        )
        .map_err(|error| InstallJobFailure::normal(error.to_string()))?;
    let mut journal = ActivationJournal::begin(
        activation_journal_path(),
        model.destination.clone(),
        prior_config_fingerprint,
    )
    .map_err(|error| {
        if error.requires_recovery() {
            InstallJobFailure::recovery_required(error.to_string())
        } else {
            InstallJobFailure::normal(error.to_string())
        }
    })?;
    let model_sha256 = model.sha256.clone();
    let model = match model.activate() {
        Ok(model) => model,
        Err(error) if error.requires_recovery() => {
            return Err(InstallJobFailure::recovery_required(error.to_string()));
        }
        Err(error) => return Err(failure_after_safe_rollback(journal, error.to_string())),
    };
    if let Err(error) = journal.mark(ActivationPhase::ModelActivated) {
        return Err(failure_after_activated_artifact_rollback(
            journal,
            model,
            None,
            error.to_string(),
        ));
    }
    let manifest_document = match installed_manifest::build_manifest(
        &model_id,
        manifest_source,
        true,
        model.destination(),
        &model_sha256,
        &smoke,
    ) {
        Ok(manifest) => manifest,
        Err(error) => {
            return Err(failure_after_activated_artifact_rollback(
                journal,
                model,
                None,
                error.to_string(),
            ));
        }
    };
    if let Err(error) =
        journal.record_manifest_target(installed_manifest::manifest_path_for(model.destination()))
    {
        return Err(failure_after_activated_artifact_rollback(
            journal,
            model,
            None,
            error.to_string(),
        ));
    }
    let manifest = match installed_manifest::stage_manifest(&manifest_document) {
        Ok(manifest) => manifest,
        Err(error) if error.requires_recovery() => {
            return Err(InstallJobFailure::recovery_required(error.to_string()));
        }
        Err(error) => {
            return Err(failure_after_activated_artifact_rollback(
                journal,
                model,
                None,
                error.to_string(),
            ));
        }
    };
    let remote_install = remote_install_request.map(|request| {
        config::ManagedRemoteModelInstall::trusted(
            config::RemoteGgufArtifact {
                repository: request.artifact.model_id,
                revision: request.artifact.revision,
                filename: request.artifact.filename,
                expected_size_bytes: request.artifact.size_bytes,
                expected_sha256: request.artifact.expected_sha256,
            },
            model.destination().to_path_buf(),
            request.display_name,
            request.description,
            request.languages,
            request.recommended,
        )
    });
    Ok(VerifiedInstallResult {
        model,
        manifest,
        model_sha256,
        smoke,
        journal,
        remote_install,
    })
}
fn validate_local_gguf_import(
    source_path: PathBuf,
    model_storage_dir: PathBuf,
    service: TranscriptionService,
    cancellation: InstallCancellation,
) -> Result<ValidatedLocalGgufImport, String> {
    if !source_path
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("gguf"))
    {
        return Err("Choose a local .gguf file to import.".to_owned());
    }
    let fingerprint = fingerprint_file_cancellable(&source_path, &cancellation)
        .map_err(local_gguf_import_install_error)?;
    reject_import_source_in_model_storage(&fingerprint.canonical_path, &model_storage_dir)?;
    let model_id = config::imported_gguf_model_id(&fingerprint.sha256)
        .map(ModelId::new)
        .ok_or_else(|| "The local GGUF hash was invalid.".to_owned())?;
    let filename = fingerprint
        .canonical_path
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .filter(|name| !name.trim().is_empty())
        .ok_or_else(|| "The local GGUF file has no usable filename.".to_owned())?;
    let display_name = fingerprint
        .canonical_path
        .file_stem()
        .map(|stem| stem.to_string_lossy().into_owned())
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| "Imported local GGUF".to_owned());
    let smoke = service
        .verify_installation_candidate(
            InstallationCandidate::pinned(
                model_id.clone(),
                fingerprint.canonical_path.clone(),
                ArtifactFormat::Gguf,
                fingerprint.size_bytes,
                fingerprint.sha256.clone(),
            ),
            &cancellation,
        )
        .map_err(local_gguf_import_error)?;
    let after_smoke = fingerprint_file_cancellable(&fingerprint.canonical_path, &cancellation)
        .map_err(local_gguf_import_install_error)?;
    ensure_local_gguf_fingerprint_unchanged(&fingerprint, &after_smoke)?;
    let install = config::ImportedGgufModelInstall::validated(
        fingerprint.canonical_path.clone(),
        fingerprint.size_bytes,
        fingerprint.sha256.clone(),
        display_name,
    );
    let manifest = installed_manifest::build_manifest(
        &model_id,
        installed_manifest::ArtifactSource::local_import(
            filename,
            fingerprint.size_bytes,
            fingerprint.sha256,
        ),
        true,
        &fingerprint.canonical_path,
        &after_smoke.sha256,
        &smoke,
    )
    .map_err(|error| format!("Could not prepare local import receipt: {error}"))?;
    Ok(ValidatedLocalGgufImport {
        model_id,
        install,
        manifest,
        smoke,
    })
}

fn reject_import_source_in_model_storage(
    canonical_source_path: &Path,
    model_storage_dir: &Path,
) -> Result<(), String> {
    let canonical_storage_dir = match fs::canonicalize(model_storage_dir) {
        Ok(path) => path,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(error) => {
            return Err(format!(
                "Could not inspect Scribe model storage {}: {error}",
                model_storage_dir.display()
            ));
        }
    };
    if canonical_source_path.starts_with(&canonical_storage_dir) {
        return Err(
            "Choose a GGUF outside Scribe's managed model storage. Local imports must remain external to Scribe."
                .to_owned(),
        );
    }
    Ok(())
}

fn ensure_local_gguf_fingerprint_unchanged(
    before: &crate::installations::FileFingerprint,
    after_smoke: &crate::installations::FileFingerprint,
) -> Result<(), String> {
    if before == after_smoke {
        Ok(())
    } else {
        Err(
            "The local GGUF changed during validation. It was not imported; choose it again to revalidate its current bytes."
                .to_owned(),
        )
    }
}

fn local_gguf_import_install_error(error: InstallError) -> String {
    match error {
        InstallError::Cancelled { .. } => {
            "Local GGUF import was cancelled. The source file was left unchanged.".to_owned()
        }
        error => format!("Local GGUF could not be loaded by the embedded runtime: {error}"),
    }
}

fn local_gguf_import_error(error: anyhow::Error) -> String {
    if matches!(
        error.downcast_ref::<InstallError>(),
        Some(InstallError::Cancelled { .. })
    ) {
        "Local GGUF import was cancelled. The source file was left unchanged.".to_owned()
    } else {
        format!("Local GGUF could not be loaded by the embedded runtime: {error}")
    }
}

fn should_activate_installed_model(active_model_is_runnable: bool) -> bool {
    !active_model_is_runnable
}

fn uses_artifact_only_install(config: &AppConfig, model: &SttModelInfo) -> bool {
    TranscriptionService::install_plan_for_config(config, &ModelId::new(&model.id)).is_some()
        || config::remote_gguf_artifact(config, &model.id).is_some()
        || config::imported_gguf_artifact(config, &model.id).is_some()
}

fn supports_managed_install(config: &AppConfig, model: &SttModelInfo) -> bool {
    model.download_model.is_some() && uses_artifact_only_install(config, model)
}

fn supports_managed_uninstall(model: &SttModelInfo, install_status: &ModelInstallStatus) -> bool {
    crate::model_catalog::normalized_install_artifact(&ModelId::new(&model.id)).is_some()
        && install_status.is_runnable()
}

fn cleanup_excluded_bundled_model(config: &AppConfig) -> Result<bool, InstallError> {
    cleanup_excluded_bundled_model_at(config, config::bundled_model_path())
}

fn cleanup_excluded_bundled_model_at(
    config: &AppConfig,
    bundled_path: Option<PathBuf>,
) -> Result<bool, InstallError> {
    if !config
        .general
        .excluded_bundled_model_ids
        .iter()
        .any(|id| id == BUNDLED_BASE_MODEL_ID)
    {
        return Ok(false);
    }
    let Some(path) = bundled_path else {
        return Ok(false);
    };
    remove_exact_regular_file(&path, &path)
}

fn apply_removed_model_config(
    config: &mut AppConfig,
    model_id: &str,
    replacement: Option<&SttModelInfo>,
    exclude_bundled: bool,
) {
    config.general.managed_models.remove(model_id);
    config.general.managed_remote_models.remove(model_id);
    config.general.imported_gguf_models.remove(model_id);
    config.general.model_paths.remove(model_id);
    set_model_selected(config, model_id, false);
    if config.general.selected_default_model == model_id {
        config.general.selected_default_model =
            replacement.map_or_else(String::new, |model| model.id.clone());
    }
    if exclude_bundled {
        config
            .general
            .excluded_bundled_model_ids
            .push(BUNDLED_BASE_MODEL_ID.to_owned());
    }
    config::normalize_config(config);
}

