    #[test]
    fn manage_models_keyboard_navigation_focuses_the_models_heading_next_frame() {
        for sidebar_entry in [true, false] {
            let ctx = egui::Context::default();
            ctx.enable_accesskit();
            configure_stitch_style(&ctx);
            let mut app = test_app();
            let installed_fixture = install_test_catalog_model(&mut app, "whisper_cpp_base_en");
            app.current_tab = if sidebar_entry {
                Tab::History
            } else {
                Tab::Transcribe
            };
            let trigger_id = egui::Id::new(if sidebar_entry {
                "active-model-trigger"
            } else {
                "selected-model-action"
            });
            let popup_id = egui::Id::new(if sidebar_entry {
                "sidebar-ready-model-picker"
            } else {
                "quick-model-picker"
            });
            ctx.memory_mut(|memory| memory.request_focus(trigger_id));

            let opened =
                render_app_navigation_frame(&ctx, &mut app, vec![pressed_key(egui::Key::Enter)]);
            assert!(ctx.memory(|memory| memory.is_popup_open(popup_id)));
            let manage_id = opened
                .platform_output
                .accesskit_update
                .as_ref()
                .unwrap()
                .nodes
                .iter()
                .find_map(|(id, node)| {
                    node.name()
                        .is_some_and(|name| name.starts_with("Manage models"))
                        .then_some(*id)
                })
                .expect("ready-model picker should expose Manage models");

            let focused_menu = render_app_navigation_frame(
                &ctx,
                &mut app,
                vec![egui::Event::AccessKitActionRequest(
                    egui::accesskit::ActionRequest {
                        action: egui::accesskit::Action::Focus,
                        target: manage_id,
                        data: None,
                    },
                )],
            );
            assert_eq!(
                focused_menu
                    .platform_output
                    .accesskit_update
                    .as_ref()
                    .unwrap()
                    .focus,
                manage_id
            );

            let navigated =
                render_app_navigation_frame(&ctx, &mut app, vec![pressed_key(egui::Key::Enter)]);
            assert_eq!(app.current_tab, Tab::Models);
            assert!(app.models_route_focus_pending);
            assert!(!ctx.memory(|memory| memory.is_popup_open(popup_id)));
            assert_ne!(ctx.memory(|memory| memory.focused()), Some(trigger_id));
            let navigated_update = navigated.platform_output.accesskit_update.as_ref().unwrap();
            assert!(!navigated_update.nodes.iter().any(|(id, node)| {
                *id == navigated_update.focus
                    && node.role() == egui::accesskit::Role::Heading
                    && node.name() == Some("Models")
            }));

            let settled = render_app_navigation_frame(&ctx, &mut app, Vec::new());
            assert!(!app.models_route_focus_pending);
            let update = settled.platform_output.accesskit_update.as_ref().unwrap();
            let focused = update
                .nodes
                .iter()
                .find(|(id, _)| *id == update.focus)
                .map(|(_, node)| node)
                .expect("focused Models destination should remain in the accessibility tree");
            assert_eq!(focused.role(), egui::accesskit::Role::Heading);
            assert_eq!(focused.name(), Some("Models"));
            assert_ne!(ctx.memory(|memory| memory.focused()), Some(trigger_id));

            let _ = fs::remove_file(installed_fixture);
        }
    }

    #[test]
    fn focused_final_playground_control_scrolls_the_outer_production_route() {
        let width = 840.0;
        let height = 420.0;
        let ctx = egui::Context::default();
        ctx.enable_accesskit();
        configure_stitch_style(&ctx);
        ctx.set_visuals(stitch_visuals(ThemeMode::Light));
        let mut app = test_app();
        app.current_tab = Tab::Debug;
        assert_eq!(app.playground_cards.len(), 1);

        let initial =
            render_debug_route_with_input(&ctx, &mut app, width, height, Vec::new(), Some(0.0));
        let target = initial
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes
            .iter()
            .filter(|(_, node)| {
                node.role() == egui::accesskit::Role::Button && node.name() == Some("Clear")
            })
            .max_by(|(_, left), (_, right)| {
                left.bounds()
                    .unwrap()
                    .y1
                    .total_cmp(&right.bounds().unwrap().y1)
            })
            .map(|(id, _)| *id)
            .expect("final Playground card should expose a Clear action");
        let _ = render_debug_route_with_input(
            &ctx,
            &mut app,
            width,
            height,
            vec![egui::Event::AccessKitActionRequest(
                egui::accesskit::ActionRequest {
                    action: egui::accesskit::Action::Focus,
                    target,
                    data: None,
                },
            )],
            Some(0.1),
        );
        let _ = render_debug_route_with_input(&ctx, &mut app, width, height, Vec::new(), Some(0.2));
        let settled =
            render_debug_route_with_input(&ctx, &mut app, width, height, Vec::new(), Some(1.0));
        let target_bounds = settled
            .platform_output
            .accesskit_update
            .as_ref()
            .unwrap()
            .nodes
            .iter()
            .find(|(id, _)| *id == target)
            .and_then(|(_, node)| node.bounds())
            .expect("focused Playground action should remain accessible");
        let (_, offset, content_size, viewport) = ctx
            .data(|data| {
                data.get_temp::<(egui::Id, egui::Vec2, egui::Vec2, egui::Rect)>(egui::Id::new(
                    "route-scroll-diagnostics",
                ))
            })
            .expect("production Debug route should expose scroll diagnostics in tests");
        assert!(
            content_size.y > viewport.height() && offset.y > 0.0,
            "final Playground focus must advance the overflowing production route"
        );
        let visible_y0 = target_bounds.y0 - f64::from(offset.y);
        let visible_y1 = target_bounds.y1 - f64::from(offset.y);
        assert!(
            visible_y0 >= f64::from(viewport.min.y) - 1.0
                && visible_y1 <= f64::from(viewport.max.y) + 1.0,
            "focused Playground action must be visible; bounds={target_bounds:?}, offset={offset:?}, viewport={viewport:?}"
        );
    }

