    #[test]
    fn clearing_history_search_immediately_loads_an_unfiltered_first_page() {
        let mut app = test_app();
        let history_root = std::env::temp_dir().join(format!(
            "scribe-history-clear-search-{}-{}",
            std::process::id(),
            NEXT_TEST_SESSION.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&history_root);
        let store = HistoryStore::open(&history_root, HistoryRetentionPolicy::default()).unwrap();
        for text in ["matching transcript", "other transcript"] {
            let record = store
                .create_pending(
                    NewHistoryEntry {
                        raw_text: text.into(),
                        model_id: "model".into(),
                        source_app: None,
                        metrics: HistoryMetrics::default(),
                    },
                    None,
                )
                .unwrap();
            store
                .complete(
                    record.id,
                    CompletedHistoryEntry {
                        raw_text: text.into(),
                        final_text: text.into(),
                        metrics: HistoryMetrics::default(),
                    },
                )
                .unwrap();
        }
        app.history_store = Some(store.clone());
        app.history_search = "matching".into();
        app.history_applied_search = "matching".into();
        app.history_records = store
            .search(HistoryQuery {
                text: Some("matching".into()),
                limit: 20,
                ..HistoryQuery::default()
            })
            .unwrap()
            .records;
        assert_eq!(app.history_records.len(), 1);

        app.apply_history_action(HistoryPageAction::ClearSearch);

        assert!(app.history_search.is_empty());
        assert!(app.history_applied_search.is_empty());
        assert!(
            app.history_search_focus_pending,
            "clearing history must return focus to the search input next frame"
        );
        assert!(app.history_records.is_empty());
        assert!(
            app.history_loading,
            "clear must start the page-one reload directly"
        );
        assert_eq!(app.history_next, None);

        let deadline = Instant::now() + Duration::from_secs(2);
        while app.history_loading {
            app.poll_events();
            assert!(
                Instant::now() < deadline,
                "unfiltered history query did not finish"
            );
            thread::sleep(Duration::from_millis(10));
        }
        assert_eq!(app.history_records.len(), 2);
        assert!(
            app.history_records
                .iter()
                .any(|record| record.raw_text == "matching transcript")
        );
        assert!(
            app.history_records
                .iter()
                .any(|record| record.raw_text == "other transcript")
        );
        drop(app);
        drop(store);
        let _ = std::fs::remove_dir_all(history_root);
    }

    #[test]
    fn history_card_expansion_is_ephemeral_and_delete_cancel_restores_more_actions_focus() {
        let mut app = test_app();
        let record = HistoryRecord {
            id: 31,
            created_at_ms: 1,
            updated_at_ms: 1,
            completed_at_ms: Some(1),
            status: HistoryStatus::Completed,
            raw_text: "saved transcript".to_owned(),
            final_text: Some("saved transcript".to_owned()),
            model_id: "whisper_cpp_base_en".to_owned(),
            metrics: HistoryMetrics::default(),
            pinned: false,
            source_app: None,
            audio_path: None,
            failure: None,
            retry_count: 0,
            output_outcome: None,
        };
        app.history_records = vec![record.clone()];

        app.apply_history_action(HistoryPageAction::ToggleTranscript(record.id));
        app.apply_history_action(HistoryPageAction::ToggleDetails(record.id));
        assert!(app.history_expanded_transcripts.contains(&record.id));
        assert!(app.history_expanded_details.contains(&record.id));
        assert_eq!(app.history_more_focus_pending, Some(record.id));

        app.apply_history_action(HistoryPageAction::RequestDelete(record.id));
        assert_eq!(app.history_delete_confirmation, Some(record.id));
        assert!(app.history_confirmation_focus_pending);
        app.apply_history_action(HistoryPageAction::CancelDelete);
        assert_eq!(app.history_delete_confirmation, None);
        assert_eq!(app.history_more_focus_pending, Some(record.id));

        app.apply_history_action(HistoryPageAction::Retry(record.id));
        assert_eq!(app.history_more_focus_pending, Some(record.id));

        app.history_records.clear();
        app.prune_history_card_ui_state();
        assert!(app.history_expanded_transcripts.is_empty());
        assert!(app.history_expanded_details.is_empty());
        assert_eq!(app.history_more_focus_pending, None);
    }

