    fn render_page_body_width(width: f32) -> f32 {
        let ctx = egui::Context::default();
        configure_stitch_style(&ctx);
        ctx.set_visuals(stitch_visuals(ThemeMode::Light));

        let raw_input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(width, 760.0),
            )),
            ..Default::default()
        };
        let mut observed_width = 0.0;

        let _ = ctx.run(raw_input, |ctx| {
            let mut current_tab = Tab::Debug;
            show_test_navigation(ctx, &mut current_tab);
            egui::CentralPanel::default()
                .frame(content_panel_frame(ctx))
                .show(ctx, |ui| {
                    show_route_scroll(ui, UiRoute::Debug, |ui| {
                        page(
                            ui,
                            "Model Playground",
                            TranscriptionStatus::Idle,
                            "Ready",
                            |ui| {
                                observed_width = usable_width(ui);
                            },
                        );
                    });
                });
        });

        observed_width
    }

    fn render_viewport_background(width: f32) -> egui::FullOutput {
        let ctx = egui::Context::default();
        configure_stitch_style(&ctx);
        ctx.set_visuals(stitch_visuals(ThemeMode::Light));

        let raw_input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(width, 760.0),
            )),
            ..Default::default()
        };

        ctx.run(raw_input, |ctx| {
            paint_viewport_background(ctx);
        })
    }

    fn render_playground_result_editor_height(width: f32) -> f32 {
        let ctx = egui::Context::default();
        configure_stitch_style(&ctx);
        ctx.set_visuals(stitch_visuals(ThemeMode::Light));

        let raw_input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(width, 760.0),
            )),
            ..Default::default()
        };
        let transcript = "wrapped result line\n".repeat(48);
        let mut allocated_height = 0.0;

        let _ = ctx.run(raw_input, |ctx| {
            egui::CentralPanel::default()
                .frame(content_panel_frame(ctx))
                .show(ctx, |ui| {
                    allocated_height = playground_result_editor(ui, "test-result", &transcript)
                        .rect
                        .height();
                });
        });

        allocated_height
    }

    fn render_models_page(width: f32) -> egui::FullOutput {
        let ctx = egui::Context::default();
        configure_stitch_style(&ctx);
        ctx.set_visuals(stitch_visuals(ThemeMode::Light));

        let raw_input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(width, 760.0),
            )),
            ..Default::default()
        };
        let mut app = test_app();

        ctx.run(raw_input, |ctx| {
            show_test_navigation(ctx, &mut app.current_tab);
            egui::CentralPanel::default()
                .frame(content_panel_frame(ctx))
                .show(ctx, |ui| {
                    show_route_scroll(ui, UiRoute::Models, |ui| app.ui_models(ui))
                });
        })
    }

    fn render_app_tab(tab: Tab, width: f32) -> egui::FullOutput {
        let ctx = egui::Context::default();
        ctx.enable_accesskit();
        configure_stitch_style(&ctx);
        ctx.set_visuals(stitch_visuals(ThemeMode::Light));

        let raw_input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(width, 760.0),
            )),
            ..Default::default()
        };
        let mut app = test_app();
        app.current_tab = tab;
        match tab {
            Tab::Advanced => {
                app.settings_tab = SettingsTab::Advanced;
                app.current_tab = Tab::General;
            }
            Tab::About => {
                app.settings_tab = SettingsTab::About;
                app.current_tab = Tab::General;
            }
            Tab::Debug => {
                app.config.developer.debug_mode = true;
                app.settings_tab = SettingsTab::Advanced;
                app.current_tab = Tab::General;
                app.settings_playground_open = true;
                app.settings_playground_needs_initial_focus = true;
            }
            _ => {}
        }

        ctx.run(raw_input, |ctx| {
            show_test_navigation(ctx, &mut app.current_tab);
            egui::CentralPanel::default()
                .frame(content_panel_frame(ctx))
                .show(ctx, |ui| match app.current_tab {
                    Tab::Transcribe => {
                        show_route_scroll(ui, UiRoute::Transcribe, |ui| app.ui_transcribe(ui))
                    }
                    Tab::General => {
                        show_route_scroll(ui, UiRoute::Settings(app.settings_tab), |ui| {
                            if app.settings_playground_open {
                                app.ui_playground(ui)
                            } else {
                                app.ui_general_settings(ui)
                            }
                        })
                    }
                    Tab::Models => show_route_scroll(ui, UiRoute::Models, |ui| app.ui_models(ui)),
                    Tab::History => {
                        show_route_scroll(ui, UiRoute::History, |ui| app.ui_history(ui))
                    }
                    Tab::Advanced => unreachable!("advanced navigation is routed to Settings"),
                    Tab::About => {
                        show_route_scroll(ui, UiRoute::Settings(SettingsTab::About), |ui| {
                            app.ui_general_settings(ui)
                        })
                    }
                    Tab::Debug => show_route_scroll(ui, UiRoute::Debug, |ui| app.ui_playground(ui)),
                });
        })
    }

    fn render_app_navigation_frame(
        ctx: &egui::Context,
        app: &mut LocalTranscriberApp,
        events: Vec<egui::Event>,
    ) -> egui::FullOutput {
        let focus_models_route_heading = std::mem::take(&mut app.models_route_focus_pending);
        ctx.run(
            egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::Pos2::ZERO,
                    egui::vec2(1_180.0, 815.0),
                )),
                focused: true,
                events,
                ..Default::default()
            },
            |ctx| {
                let sidebar_models = Arc::clone(&app.remote_catalog.local_models);
                let selected_model_id = app.config.general.selected_default_model.clone();
                let (_, model_action) = show_navigation(
                    ctx,
                    &mut app.current_tab,
                    false,
                    ResolvedTheme::Light,
                    SidebarModelView {
                        selected_model_id: Some(&selected_model_id),
                        models: &sidebar_models,
                        disabled_reason: None,
                    },
                );
                if let Some(action) = model_action {
                    app.apply_ready_model_picker_action(action);
                }
                egui::CentralPanel::default()
                    .frame(content_panel_frame(ctx))
                    .show(ctx, |ui| match app.current_tab {
                        Tab::Transcribe => {
                            show_route_scroll(ui, UiRoute::Transcribe, |ui| app.ui_transcribe(ui))
                        }
                        Tab::Models => show_route_scroll(ui, UiRoute::Models, |ui| {
                            if focus_models_route_heading {
                                request_models_route_heading_focus(ui.ctx());
                            }
                            app.ui_models(ui)
                        }),
                        Tab::History => {
                            show_route_scroll(ui, UiRoute::History, |ui| app.ui_history(ui))
                        }
                        _ => unreachable!("focus-route test uses primary non-settings pages"),
                    });
            },
        )
    }

