    fn remote_catalog_model(
        id: &str,
        display_name: &str,
        languages: &[&str],
        recommended: bool,
        variant_size_bytes: u64,
    ) -> RemoteModel {
        RemoteModel {
            id: id.to_owned(),
            revision: "a".repeat(40),
            display_name: display_name.to_owned(),
            description: format!("{display_name} description"),
            languages: languages
                .iter()
                .map(|language| (*language).to_owned())
                .collect(),
            recommended,
            trust: crate::huggingface_catalog::ModelTrust::TrustedPublisher,
            compatibility: crate::huggingface_catalog::ModelCompatibility::Experimental(
                "Fixture only".to_owned(),
            ),
            variants: vec![crate::huggingface_catalog::RemoteModelVariant {
                id: "q4".to_owned(),
                filename: "fixture.gguf".to_owned(),
                size_bytes: variant_size_bytes,
                expected_sha256: "b".repeat(64),
            }],
        }
    }

    fn partial_cleanup_test_root(name: &str) -> PathBuf {
        std::env::temp_dir().join(format!(
            "scribe-app-partial-{name}-{}-{}",
            std::process::id(),
            NEXT_TEST_SESSION.fetch_add(1, Ordering::Relaxed)
        ))
    }

    fn partial_sidecar(destination: &Path) -> PathBuf {
        destination.with_file_name(format!(
            "{}.partial",
            destination.file_name().unwrap().to_string_lossy()
        ))
    }

    fn trusted_fixture_destination(
        config: &AppConfig,
        model: &RemoteModel,
        variant_id: &str,
    ) -> PathBuf {
        let artifact = model.artifact_for(variant_id).unwrap();
        config::model_storage_dir(config)
            .join("huggingface")
            .join("handy-computer")
            .join(model.id.strip_prefix("handy-computer/").unwrap())
            .join(&model.revision)
            .join(
                config::managed_remote_model_id(
                    &artifact.model_id,
                    &artifact.revision,
                    &artifact.filename,
                )
                .unwrap(),
            )
            .join(&artifact.filename)
    }

    fn wait_for_remote_partial_inspections(app: &mut LocalTranscriberApp) {
        for _ in 0..100 {
            app.poll_events();
            if app.remote_catalog.pending_partial_inspections.is_empty() {
                return;
            }
            thread::sleep(Duration::from_millis(5));
        }
        panic!("remote partial inspection did not finish");
    }

