    #[test]
    fn onnx_recovery_failure_freezes_future_artifact_mutations() {
        let mut app = test_app();
        let model_id = "moonshine-tiny-en-int8-onnx".to_owned();
        app.onnx_bundle_install = Some(test_onnx_bundle_install_job(
            53,
            model_id.clone(),
            InstallCancellation::default(),
        ));
        app.tx
            .send(AppEvent::OnnxBundleInstallFinished {
                job_id: 53,
                model_id,
                paused: false,
                recovery_required: true,
                result: Err("interrupted ONNX activation needs reconciliation".to_owned()),
            })
            .unwrap();

        app.poll_events();

        assert!(matches!(app.status, TranscriptionStatus::Error));
        assert!(app.artifact_installations.recovery_is_frozen());
        assert!(
            app.artifact_recovery_error
                .as_deref()
                .is_some_and(|message| message.contains("interrupted ONNX activation"))
        );
        assert!(app.artifact_mutation_block_reason().is_some());
        assert!(app.onnx_bundle_install.is_none());
    }

    #[cfg(unix)]
    #[test]
    fn uninstall_removes_managed_model_file_and_selects_next_installed_model() {
        let temp_dir =
            std::env::temp_dir().join(format!("scribe-uninstall-test-{}", std::process::id()));
        let _ = fs::remove_dir_all(&temp_dir);
        let model_dir = temp_dir.join("gguf");
        fs::create_dir_all(&model_dir).unwrap();
        let base_path = model_dir.join("whisper-base.en-Q8_0.gguf");
        let small_path = model_dir.join("whisper-small.en-Q8_0.gguf");
        fs::write(&base_path, b"base").unwrap();
        fs::write(&small_path, b"small").unwrap();

        let mut config = AppConfig::default();
        config.general.selected_default_model = "whisper_cpp_base_en".to_owned();
        config.general.model_storage_dir = temp_dir.clone();
        config.general.managed_models.insert(
            "whisper_cpp_base_en".to_owned(),
            config::ManagedModelInstall::app_managed(base_path.clone(), "test"),
        );
        config.general.managed_models.insert(
            "whisper_cpp_small_en".to_owned(),
            config::ManagedModelInstall::app_managed(small_path.clone(), "test"),
        );

        let removal =
            ManagedRemoval::stage(&base_path, std::slice::from_ref(&base_path), "0".repeat(64))
                .unwrap();
        assert!(removal.removed_files());
        removal.commit().unwrap();
        assert!(!base_path.exists());
        config.general.managed_models.remove("whisper_cpp_base_en");
        select_first_installed_model(&mut config);

        assert_eq!(
            config.general.selected_default_model,
            "whisper_cpp_small_en"
        );

        let _ = fs::remove_dir_all(&temp_dir);
    }

